insert into public.opciones_venta(producto_id,nombre,peso_aprox_kg,unidades_incluidas,factor_precio,activa,orden) select id,v.n,null,null,1,true,v.o from public.productos cross join (values ('Petit',1),('Mitjà',2),('Gran',3)) v(n,o) where familia='Turró';
insert into public.opciones_venta(producto_id,nombre,unidades_incluidas,factor_precio,activa,orden) select id,'½ dotzena',6,.5,true,1 from public.productos where familia in ('Roscos de vi','Polvoró','Mantegat');
insert into public.opciones_venta(producto_id,nombre,unidades_incluidas,factor_precio,activa,orden) select id,'1 dotzena',12,1,true,2 from public.productos where familia in ('Roscos de vi','Polvoró','Mantegat');
insert into public.opciones_venta(producto_id,nombre,factor_precio,activa,orden) select id,'10 persones',1,true,1 from public.productos where codigo='TOR001';
insert into public.opciones_venta(producto_id,nombre,factor_precio,activa,orden) select id,v.n,1,true,v.o from public.productos cross join (values ('Nata · 10 persones',1),('Trufa · 10 persones',2),('Crema · 10 persones',3)) v(n,o) where codigo='TOR002';
insert into public.opciones_venta(producto_id,nombre,peso_aprox_kg,factor_precio,activa,orden) select id,v.n,.5,1,true,v.o from public.productos cross join (values ('Fruita · 500 g',1),('Xocolata · 500 g',2)) v(n,o) where codigo='PAN001';
